import { ListType } from "./types/data";
import './Home.css';
import { Button, Stack, Typography } from "@mui/material";
import { useNavigate } from "react-router-dom";
import ProductenPerMerk from "./components/BrandProducts";
import Leveranciers from "./components/Growers";
import Loader from "./components/Loader";
import Shops from "./components/Shops";

type Props = {
    productList: ListType;
};

export default function PageHome({ productList }: Props) {
    const navigate = useNavigate();
    const heroImage = process.env.REACT_APP_HOME_HERO_IMAGE || "https://images.unsplash.com/photo-1536816579748-4ecb3f03d72a?auto=format&fit=crop&w=1800&q=80";
    
    const handleOpenAllProducts = () => {
        navigate('/cannabis'); 
    }
    const handleOpenAllGrowers = () => {
        navigate('/telers');
    };
    const handleOpenAllShops = () => {
        navigate('/kaart');
    };

    return (
        <section className="home-container">
            <section
                className="home-hero"
                style={{
                    backgroundImage: `linear-gradient(rgba(8, 22, 10, 0.65), rgba(8, 22, 10, 0.65)), url(${heroImage})`,
                }}
            >
                <div className="home-hero-content">
                    <Typography component="h1" variant="h3" sx={{ fontWeight: 800, lineHeight: 1.1, color: "#fff", mb: 1 }}>
                        WeedInfo
                    </Typography>
                    <Typography variant="h6" sx={{ color: "rgba(255,255,255,0.95)", mb: 2 }}>
                        Jouw gids voor soorten, telers en coffeeshops in een duidelijke ervaring.
                    </Typography>
                    <Button variant="contained" color="success" onClick={handleOpenAllShops}>
                        Vind coffeeshops in de buurt
                    </Button>
                </div>
            </section>
            <section id="headerInfo" style={{ textAlign: 'left', margin: "16px 8px 28px" }}>
                <Typography component="h2" variant="h5" sx={{ color: 'text.secondary', fontWeight: 600 }}>
                    Waarom deze applicatie ?
                </Typography>
                <Typography variant="body1" sx={{ color: 'text.secondary' }}>
                    Sinds het Experiment "gesloten cannabis keten" van de overheid, is legale teelt en verkoop mogelijk van cannabis dat niet langer meer via het gedoogdbeleid gaat.
                    De geselecteerde telers verkopen dus aan de Cannabis winkels maar geven geen duidelijke informatie over de verkochte soortjes anders dan het THC gehalte, de naam en een eventuele bijsluiter over het gebruik in het algemeen.
                </Typography>
                <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                    Wij willen iedereen de juiste informatie verschaffen gemaakt door de telers en aangevuld door de gebruikers, daadwerkelijk weten wat en waar je het koopt.
                </Typography>
            </section>

            <section id="cannabisStrains">
                {productList.loading && (
                    <Loader size={40} display="block" />
                )}
                <Stack direction="row" sx={{ justifyContent: "space-between", alignItems: "center", mb: 1.5, px: 1 }}>
                    <Typography component="h2" variant="h5" sx={{ color: 'text.secondary', fontWeight: 600, textAlign: "left" }}>
                        Veel gezochte soortjes
                    </Typography>
                    <Button size="small" color="success" variant="contained" onClick={handleOpenAllProducts}>
                        Alle Cannabis
                    </Button>
                </Stack>
                <ProductenPerMerk limit={8} sortByViews carouselOnMobile />
            </section>

            <br /><br /><br />
            <section id="growerInfo" style={{ textAlign: 'left', margin: "16px 8px 28px" }}>
                <Typography variant="body1" sx={{ color: 'text.secondary' }}>
                    Er is aan handjevol telers aangewezen voor dit experiment, deze telers mogen legaal hun activiteiten uitvoeren onder het gecontrolleerde en gereguleerde systeem.
                </Typography>
            </section>

            <section id="cannabisGrowers">
                <Stack direction="row" sx={{ justifyContent: "space-between", alignItems: "center", mb: 1.5, px: 1 }}>
                    <Typography component="h2" variant="h5" sx={{ color: 'text.secondary', fontWeight: 600 }}>
                        Geselecteerde Telers
                    </Typography>
                    <Button size="small" color="success" variant="contained" onClick={handleOpenAllGrowers}>
                        Alle Telers
                    </Button>
                </Stack>
                <Leveranciers limit={8} carouselOnMobile />
            </section>

            <section id="shopInfo" style={{ textAlign: "left", margin: "16px 8px 28px" }}>
                <Typography variant="body1" sx={{ color: "text.secondary" }}>
                    Dit zijn de aangesloten coffeeshops uit de actuele dataset.
                </Typography>
            </section>
            <section id="selectedShops">
                <Stack direction="row" sx={{ justifyContent: "space-between", alignItems: "center", mb: 1.5, px: 1 }}>
                    <Typography component="h2" variant="h5" sx={{ color: "text.secondary", fontWeight: 600 }}>
                        Geselecteerde Coffeeshops
                    </Typography>
                    <Button size="small" color="success" variant="contained" onClick={handleOpenAllShops}>
                        Alle Winkels
                    </Button>
                </Stack>
                <Shops limit={8} carouselOnMobile />
            </section>
            
        </section>
    )
}


